package dev.redstoneengineering.block;
import com.mojang.serialization.MapCodec;import dev.redstoneengineering.RedstoneEngineering;import dev.redstoneengineering.physics.*;import net.minecraft.core.*;import net.minecraft.network.chat.Component;import net.minecraft.server.level.ServerLevel;import net.minecraft.world.*;import net.minecraft.world.entity.player.Player;import net.minecraft.world.level.*;import net.minecraft.world.level.block.Block;import net.minecraft.world.level.block.state.BlockState;import net.minecraft.world.phys.BlockHitResult;
/** Converts one 8-bit bus word into a framed serial payload. */
public class SerializerBlock extends DirectionalDomainBlock{public SerializerBlock(Properties p){super(p);}@Override public MapCodec<SerializerBlock> codec(){return RedstoneEngineering.SERIALIZER_CODEC.value();}private void update(ServerLevel l,BlockPos p,BlockState s){BlockPos in=inputPos(p,s),out=outputPos(p,s);int v=DataBusNetwork.sample(l,in);boolean ok=DataBusNetwork.valid(l,in);InformationRuntime.write(l,"serial",p,v,8,ok,100);if(l.getBlockState(out).getBlock() instanceof SerialDataLineBlock)SerialNetwork.drive(l,out,v,8,ok,100);}@Override protected void onPlace(BlockState s,Level l,BlockPos p,BlockState o,boolean m){super.onPlace(s,l,p,o,m);if(l instanceof ServerLevel sl)update(sl,p,s);}@Override protected void neighborChanged(BlockState s,Level l,BlockPos p,Block nb,BlockPos np,boolean m){if(l instanceof ServerLevel sl)update(sl,p,s);}@Override protected InteractionResult useWithoutItem(BlockState s,Level l,BlockPos p,Player pl,BlockHitResult h){if(!l.isClientSide)pl.displayClientMessage(Component.literal("Serializer framed byte="+InformationRuntime.value(l,"serial",p)+" @ 8t/word"),true);return InteractionResult.sidedSuccess(l.isClientSide);}}
